tmp=$(mktemp -d);trap 'rm -rf "$tmp"' EXIT;for x in "${paths[@]}";do printf 'A\t%s\n' "$x";done|sort>"$tmp/w";git diff-tree --no-commit-id --name-status -r "$base" "$src"|sort>"$tmp/a";cmp -s "$tmp/w" "$tmp/a"||exit 1;for i in "${!paths[@]}";do read -r m _ _ x< <(git ls-files --stage -- "${paths[$i]}");[[ "$m" == "${modes[$i]}" && "$x" == "${paths[$i]}" ]]||exit 1;done
python3 scripts/eval/check_${stem}.py>"$tmp/o";cmp -s scripts/eval/fixtures/${stem}.expected.v0.tsv "$tmp/o";python3 scripts/eval/check_${stem}.py --self-test|grep -qx $'self_test_boundary\tpass';printf 't17_custody_authority_gate\tpass\nvalidation_tier\t%s\nrelease_topology\t%s\npacket_path_count\t7\ndecision_implements_components\t0\ndecision_consumes_authority\tfalse\n' "$tier" "$mode"
